import{_ as s,o as e,c as i,a5 as t}from"./chunks/framework.C588jwcu.js";const k=JSON.parse('{"title":"会話ボックスのカスタマイズ","description":"","frontmatter":{"title":"会話ボックスのカスタマイズ","order":4},"headers":[],"relativePath":"ja/latest/tutorial/develop/customize-the-dialogbox.md","filePath":"ja/latest/tutorial/develop/customize-the-dialogbox.md","lastUpdated":1785683504000}'),o={name:"ja/latest/tutorial/develop/customize-the-dialogbox.md"};function d(l,a,n,r,h,p){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="会話インターフェースのカスタマイズ" tabindex="-1">会話インターフェースのカスタマイズ <a class="header-anchor" href="#会話インターフェースのカスタマイズ" aria-label="Permalink to &quot;会話インターフェースのカスタマイズ&quot;">​</a></h1><h2 id="紹介" tabindex="-1">紹介 <a class="header-anchor" href="#紹介" aria-label="Permalink to &quot;紹介&quot;">​</a></h2><p>会話インターフェースをカスタマイズする場合は、使用するテンプレートシーンを <code>res://ui/dialogue/</code> などプロジェクト側のディレクトリへコピーし、その複製または Godot のカスタムテーマを編集してください。</p><p><code>res://addons/konado/</code> 内のファイルを直接編集しないでください。プラグイン更新時にプラグインディレクトリが置き換わります。プロジェクト側の複製は Konado を更新しても保持されます。</p><h2 id="テンプレートファイルの編集" tabindex="-1">テンプレートファイルの編集 <a class="header-anchor" href="#テンプレートファイルの編集" aria-label="Permalink to &quot;テンプレートファイルの編集&quot;">​</a></h2><p><code>res://addons/konado/template/</code> には組み込み会話テンプレートがあります。必要な <code>.tscn</code> をプロジェクトへコピーし、会話シーンでその複製をインスタンス化して、含まれる <code>KND_DialogueBox</code> ノードを <code>KND_DialogueManager</code> の <code>_konado_dialogue_box</code> プロパティへ割り当てます。</p><p>通常はノード上のスクリプトを変更せず、ノードのプロパティを変更してカスタマイズすることを推奨します。</p><h2 id="ボイス進行表示のカスタマイズ" tabindex="-1">ボイス進行表示のカスタマイズ <a class="header-anchor" href="#ボイス進行表示のカスタマイズ" aria-label="Permalink to &quot;ボイス進行表示のカスタマイズ&quot;">​</a></h2><p>通常の会話行にボイスタグがあり、音声を再生している間は、会話ボックスに再生進行が表示されます。ボイスがない、リソースを解決できない、または再生が終了した場合は自動的に非表示になります。不要な場合は <code>KonadoDialogueBox</code> ノードの <code>show_voice_progress</code> を無効にしてください。</p><p>組み込みコンポーネントの元ファイルは <code>res://addons/konado/template/default/voice_progress_display.tscn</code> です。色、角丸、サイズ、ノード構造を変更する前にプロジェクトへコピーし、カスタマイズした会話ボックスからその複製を参照してください。完全に置き換える場合は次のインターフェースを維持します。</p><div class="language-gdscript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gdscript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> set_progress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(current: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, total: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> hide_progress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span></span></code></pre></div>`,11)])])}const g=s(o,[["render",d]]);export{k as __pageData,g as default};
